export const CLAIM_STAGES={research:'Riset awal',pre_snapshot:'Belum snapshot',snapshot:'Snapshot tercatat',awaiting_claim:'Menunggu klaim',claimed:'Diklaim · laporan pribadi',closed:'Distribusi selesai',failed:'Gagal / dibatalkan',risk_reported:'Risiko dilaporkan'};
export const TRUST_BANDS=[['0–799','Tidak dipercaya'],['800–1199','Diragukan'],['1200–1599','Netral'],['1600–1999','Cukup dipercaya'],['2000–2800','Sangat dipercaya']];
export function cleanDossier(raw={}){const txt=(v,n)=>typeof v==='string'?v.trim().slice(0,n):'';return {stage:Object.hasOwn(CLAIM_STAGES,raw.stage)?raw.stage:'research',audit:txt(raw.audit,500),team:txt(raw.team,500),treasury:txt(raw.treasury,500),chainEvidence:txt(raw.chainEvidence,500),risks:txt(raw.risks,1000),checkedAt:typeof raw.checkedAt==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(raw.checkedAt)?raw.checkedAt:'',outcome:txt(raw.outcome,1000)}}
export function cleanReview(raw){if(!raw||typeof raw.projectId!=='string'||typeof raw.text!=='string'||!raw.text.trim())throw Error('Tulis ulasan terlebih dahulu.');const rating=Number(raw.rating);if(!Number.isInteger(rating)||rating<1||rating>5)throw Error('Rating harus 1–5.');return {projectId:raw.projectId,text:raw.text.trim().slice(0,2000),rating,at:typeof raw.at==='string'?raw.at.slice(0,40):new Date().toISOString(),visibility:'local'}}
export function sourceSignals(value){let url;try{url=new URL(value)}catch{return ['URL tidak valid.']}if(url.protocol!=='https:')return ['Sumber tidak menggunakan HTTPS.'];const flags=[];if(url.username||url.password)flags.push('URL memuat kredensial; jangan lanjutkan.');if(url.hostname.split('.').some(s=>s.startsWith('xn--')))flags.push('Domain menggunakan karakter internasional (Punycode). Periksa kemiripan nama.');if(/^\d+\.\d+\.\d+\.\d+$/.test(url.hostname)||url.hostname.startsWith('['))flags.push('Alamat sumber berupa IP, bukan domain proyek.');flags.push('Sumber belum diverifikasi oleh Airdrop Museum. HTTPS bukan bukti legitimasi.');return flags}
